package com.example.jdbcdemo;

import java.io.IOException;
import java.io.InputStream;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.Properties;

public final class Database {
    private static final String CONFIG = "db.properties";
    private final String url;
    private final String user;
    private final String password;

    public Database(Properties config) {
        this.url = value(config, "db.url", "DB_URL");
        this.user = value(config, "db.user", "DB_USER");
        this.password = value(config, "db.password", "DB_PASSWORD");
    }

    public static Properties loadConfig() throws IOException {
        Properties props = new Properties();
        try (InputStream in = Database.class.getClassLoader().getResourceAsStream(CONFIG)) {
            if (in != null) {
                props.load(in);
            }
        }
        return props;
    }

    private static String value(Properties config, String key, String env) {
        String envValue = System.getenv(env);
        if (envValue != null && !envValue.isBlank()) {
            return envValue;
        }
        String propValue = config.getProperty(key);
        if (propValue == null || propValue.isBlank()) {
            throw new IllegalStateException("Missing database setting: " + key + " (or env " + env + ")");
        }
        return propValue.trim();
    }

    public Connection getConnection() throws SQLException {
        return DriverManager.getConnection(url, user, password);
    }
}
```

